// pnpm engine:pets [--check] (tsx: imports the TypeScript sources) — the pets for the native client,
// GENERATED by the web's own code: apps/client/src/player/creatureRig.ts builds each species exactly as
// the web does, and its scene tree is written to engine/assets/pets/ as
//   pets.json  per species: the collider/pace numbers (SPECIES), the skeleton numbers `update()` reads,
//              and every node (parent, rest position / Euler XYZ rotation / scale, the role `update()`
//              animates it as, and for a part its geometry and colour)
//   pets.bin   float32 positions, float32 normals, uint32 indices (little-endian, in that order)
// The app animates the nodes with a port of CreatureRig.update (engine/crates/client/src/pet.rs), so a
// change to creatureRig.ts means re-running this (CI --check fails on stale output) and, if the
// animation itself changed, changing pet.rs too. The ink hulls (HULL_LAYER, off by default) are left out.
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { CreatureRig, PET_SPECIES, SPECIES } from "../apps/client/src/player/creatureRig.ts";

const dir = fileURLToPath(new URL("../engine/assets/pets/", import.meta.url));
const positions = [];
const normals = [];
const indices = [];
let vertexBase = 0;
const geoms = new Map(); // geometry -> index in `geometries`
const geometries = [];

const r6 = (v) => Math.round(v * 1e6) / 1e6;

function geometryIndex(g) {
  if (geoms.has(g)) return geoms.get(g);
  const p = g.getAttribute("position");
  const n = g.getAttribute("normal");
  // weld identical (position, normal) corners: RoundedBoxGeometry is not indexed, three copies a corner
  const vstart = vertexBase;
  const seen = new Map();
  let count = 0;
  const istart = indices.length;
  const corners = g.index ? Array.from({ length: g.index.count }, (_, i) => g.index.getX(i)) : Array.from({ length: p.count }, (_, i) => i);
  for (const i of corners) {
    const v = [p.getX(i), p.getY(i), p.getZ(i), n.getX(i), n.getY(i), n.getZ(i)];
    const k = v.map((x) => Math.round(x * 1e5)).join(",");
    let at = seen.get(k);
    if (at === undefined) {
      at = count++;
      seen.set(k, at);
      positions.push(v[0], v[1], v[2]);
      normals.push(v[3], v[4], v[5]);
    }
    indices.push(at);
  }
  vertexBase += count;
  const id = geometries.length;
  geometries.push({ vertexStart: vstart, vertexCount: count, indexStart: istart, indexCount: indices.length - istart });
  geoms.set(g, id);
  return id;
}

const species = {};
for (const key of PET_SPECIES) {
  const rig = new CreatureRig(key);
  const built = rig["built"];
  const roles = new Map([[rig["toy"], "toy"], [rig["spine"], "spine"], [rig["head"], "head"], [rig["tail"], "tail"]]);
  rig["legs"].forEach((o, i) => roles.set(o, `leg${i}`));
  built.ears.forEach((o, i) => roles.set(o, `ear${i}`));
  built.chain.forEach((o, i) => roles.set(o, `chain${i}`));
  built.eyes.forEach((o, i) => roles.set(o, `eye${i}`));
  const nodes = [];
  const walk = (o, parent) => {
    const hull = o.isMesh && o.material.type === "ShaderMaterial";
    if (hull) return;
    const node = {
      parent,
      position: o.position.toArray().map(r6),
      rotation: [o.rotation.x, o.rotation.y, o.rotation.z].map(r6),
      scale: o.scale.toArray().map(r6),
    };
    if (o.rotation.order !== "XYZ") throw new Error(`${key}: Euler order ${o.rotation.order}`);
    const role = roles.get(o);
    if (role) node.role = role;
    if (o.isMesh) {
      node.geometry = geometryIndex(o.geometry);
      node.color = `#${o.material.color.getHexString()}`;
    }
    const id = nodes.length;
    nodes.push(node);
    for (const c of o.children) walk(c, id);
  };
  walk(rig.root, -1);
  for (const role of roles.values()) {
    if (!nodes.some((n) => n.role === role)) throw new Error(`${key}: role ${role} not in the tree`);
  }
  const sk = built.skeleton;
  const info = SPECIES[key];
  species[key] = {
    bodyWidth: info.bodyWidth,
    bodyHeight: info.bodyHeight,
    jumpSpeed: info.jumpSpeed,
    pace: info.pace,
    name: info.name,
    trait: info.trait,
    skeleton: {
      chestY: sk.chestY, chestZ: sk.chestZ, shoulderY: sk.shoulderY, sitHipY: sk.sitHipY, sitLean: sk.sitLean,
      bob: sk.bob, stride: sk.stride, cadence: sk.cadence,
    },
    tailAmp: built.tailAmp,
    tailPitch: built.tailPitch,
    nodes,
  };
}

const json = `${JSON.stringify({ species: PET_SPECIES, geometries, pets: species }, null, 1)}\n`;
const bin = Buffer.concat([
  Buffer.from(new Float32Array(positions).buffer),
  Buffer.from(new Float32Array(normals).buffer),
  Buffer.from(new Uint32Array(indices).buffer),
]);
const header = { vertices: vertexBase, indices: indices.length };
const full = json.replace("{", `{\n "vertices": ${header.vertices},\n "indices": ${header.indices},`);

if (process.argv.includes("--check")) {
  let stale = false;
  try {
    stale = readFileSync(`${dir}pets.json`, "utf8") !== full || !readFileSync(`${dir}pets.bin`).equals(bin);
  } catch {
    stale = true;
  }
  if (stale) {
    console.error("engine/assets/pets is stale: run `pnpm engine:pets`");
    process.exit(1);
  }
  console.log("engine/assets/pets is up to date");
} else {
  mkdirSync(dir, { recursive: true });
  writeFileSync(`${dir}pets.json`, full);
  writeFileSync(`${dir}pets.bin`, bin);
  console.log(`pets: ${PET_SPECIES.length} species, ${geometries.length} shapes, ${vertexBase} vertices, ${indices.length / 3} triangles, ${(bin.length / 1e6).toFixed(2)} MB`);
}
